//! Tests for CONSTANT_Dynamic (tag 17) constant pool entries.
//!
//! `CondyExample.class` is generated by `java-assets/src/CondyGen.java` with the JDK
//! Class-File API, because javac never emits CONSTANT_Dynamic. Its constant pool
//! holds three dynamic constants, each bootstrapped by a method of
//! `java.lang.invoke.ConstantBootstraps`:
//!
//! | index | bootstrap          | name | type                 | loaded by |
//! |-------|--------------------|------|----------------------|-----------|
//! | 15    | 0: nullConstant    | `_`  | `Ljava/lang/Object;` | ldc       |
//! | 26    | 1: primitiveClass  | `I`  | `Ljava/lang/Class;`  | ldc       |
//! | 37    | 2: explicitCast 42 | `_`  | `J`                  | ldc2_w    |

extern crate classfile_parser;

use std::io::Cursor;
use std::process::Command;

use binrw::BinWrite;
use binrw::prelude::*;
use classfile_parser::ClassFile;
use classfile_parser::attribute_info::{AttributeInfoVariant, BootstrapMethod};
use classfile_parser::code_attribute::Instruction;
use classfile_parser::constant_info::{ConstantInfo, DynamicConstant};

const CONDY_CLASS: &[u8] = include_bytes!("../java-assets/compiled-classes/CondyExample.class");

fn load() -> ClassFile {
    ClassFile::read(&mut Cursor::new(CONDY_CLASS)).expect("CondyExample.class should parse")
}

fn utf8(class: &ClassFile, index: u16) -> &str {
    class
        .get_utf8(index)
        .unwrap_or_else(|| panic!("#{index} is not a Utf8 constant"))
}

fn name_and_type(class: &ClassFile, index: u16) -> (&str, &str) {
    match &class.const_pool[index as usize - 1] {
        ConstantInfo::NameAndType(n) => {
            (utf8(class, n.name_index), utf8(class, n.descriptor_index))
        }
        other => panic!("#{index} is not a NameAndType constant: {other:?}"),
    }
}

/// (1-based pool index, entry) for every Dynamic constant in the pool.
fn dynamic_entries(class: &ClassFile) -> Vec<(u16, &DynamicConstant)> {
    class
        .const_pool
        .iter()
        .enumerate()
        .filter_map(|(i, entry)| match entry {
            ConstantInfo::Dynamic(d) => Some(((i + 1) as u16, d)),
            _ => None,
        })
        .collect()
}

fn bootstrap_methods(class: &ClassFile) -> &[BootstrapMethod] {
    class
        .attributes
        .iter()
        .find_map(|attr| match &attr.info_parsed {
            Some(AttributeInfoVariant::BootstrapMethods(b)) => Some(b.bootstrap_methods.as_slice()),
            _ => None,
        })
        .expect("BootstrapMethods attribute")
}

/// (owner class, method name) of a REF_invokeStatic MethodHandle constant.
fn static_handle_target(class: &ClassFile, handle_index: u16) -> (&str, &str) {
    let ConstantInfo::MethodHandle(h) = &class.const_pool[handle_index as usize - 1] else {
        panic!("#{handle_index} is not a MethodHandle constant");
    };
    assert_eq!(h.reference_kind, 6, "expected REF_invokeStatic");
    let ConstantInfo::MethodRef(m) = &class.const_pool[h.reference_index as usize - 1] else {
        panic!("#{} is not a MethodRef constant", h.reference_index);
    };
    let ConstantInfo::Class(c) = &class.const_pool[m.class_index as usize - 1] else {
        panic!("#{} is not a Class constant", m.class_index);
    };
    (
        utf8(class, c.name_index),
        name_and_type(class, m.name_and_type_index).0,
    )
}

fn code_of<'a>(class: &'a ClassFile, name: &str) -> &'a [Instruction] {
    &class
        .find_method(name)
        .unwrap_or_else(|| panic!("method {name} not found"))
        .code()
        .expect("method should have a Code attribute")
        .code
}

fn java_available() -> bool {
    Command::new("java")
        .arg("-version")
        .output()
        .map(|o| o.status.success())
        .unwrap_or(false)
}

#[test]
fn parses_dynamic_constants() {
    let class = load();
    assert_eq!(class.major_version, 55, "condy needs a Java 11+ class file");

    let summary: Vec<(u16, u16, &str, &str)> = dynamic_entries(&class)
        .into_iter()
        .map(|(index, d)| {
            let (name, descriptor) = name_and_type(&class, d.name_and_type_index);
            (index, d.bootstrap_method_attr_index, name, descriptor)
        })
        .collect();
    assert_eq!(
        summary,
        vec![
            (15, 0, "_", "Ljava/lang/Object;"),
            (26, 1, "I", "Ljava/lang/Class;"),
            (37, 2, "_", "J"),
        ]
    );
}

#[test]
fn dynamic_constants_reference_constant_bootstraps() {
    let class = load();
    let bsms = bootstrap_methods(&class);
    assert_eq!(bsms.len(), 3);

    let targets: Vec<(&str, &str)> = dynamic_entries(&class)
        .iter()
        .map(|(_, d)| {
            let bsm = &bsms[d.bootstrap_method_attr_index as usize];
            static_handle_target(&class, bsm.bootstrap_method_ref)
        })
        .collect();
    let cb = "java/lang/invoke/ConstantBootstraps";
    assert_eq!(
        targets,
        vec![
            (cb, "nullConstant"),
            (cb, "primitiveClass"),
            (cb, "explicitCast")
        ]
    );

    // explicitCast(Lookup, name, type, Object value) carries one static argument: the int 42.
    let args: Vec<&ConstantInfo> = bsms[2]
        .bootstrap_arguments
        .iter()
        .map(|&i| &class.const_pool[i as usize - 1])
        .collect();
    match args.as_slice() {
        [ConstantInfo::Integer(arg)] => assert_eq!(arg.value, 42),
        other => panic!("explicitCast should have one Integer static argument, got {other:?}"),
    }
}

#[test]
fn ldc_sites_reference_dynamic_constants() {
    let class = load();
    assert!(matches!(
        code_of(&class, "getNull"),
        [Instruction::Ldc(15), Instruction::Areturn]
    ));
    assert!(matches!(
        code_of(&class, "getIntClass"),
        [Instruction::Ldc(26), Instruction::Areturn]
    ));
    assert!(matches!(
        code_of(&class, "getLong"),
        [Instruction::Ldc2W(37), Instruction::Lreturn]
    ));
}

#[test]
fn round_trip_is_byte_identical() {
    let class = load();
    let mut out = Cursor::new(Vec::new());
    class.write(&mut out).expect("write");
    assert_eq!(out.into_inner(), CONDY_CLASS);
}

#[test]
fn get_or_add_dynamic_deduplicates_and_appends() {
    let mut class = load();
    let before = class.const_pool.len();

    assert_eq!(
        class.get_or_add_dynamic(0, "_", "Ljava/lang/Object;"),
        15,
        "an existing entry is reused"
    );
    assert_eq!(class.const_pool.len(), before);

    // Same NameAndType but a different bootstrap method: a new entry is appended.
    let added = class.get_or_add_dynamic(1, "_", "Ljava/lang/Object;");
    assert_eq!(added as usize, before + 1);
    assert_eq!(
        class.get_or_add_dynamic(1, "_", "Ljava/lang/Object;"),
        added
    );
    match &class.const_pool[added as usize - 1] {
        ConstantInfo::Dynamic(d) => {
            assert_eq!(d.bootstrap_method_attr_index, 1);
            assert_eq!(
                name_and_type(&class, d.name_and_type_index),
                ("_", "Ljava/lang/Object;")
            );
        }
        other => panic!("expected a Dynamic constant, got {other:?}"),
    }

    class.sync_counts();
    assert_eq!(class.const_pool_size as usize, class.const_pool.len() + 1);

    let mut out = Cursor::new(Vec::new());
    class.write(&mut out).expect("write");
    let reparsed = ClassFile::read(&mut Cursor::new(out.into_inner())).expect("re-read");
    assert_eq!(dynamic_entries(&reparsed).len(), 4);
}

/// A class rewritten by this crate, with an extra Dynamic entry appended, must still
/// pass the JVM's class file checks and run.
#[test]
fn rewritten_class_runs_on_the_jvm() {
    if !java_available() {
        eprintln!("skipping: java is not available");
        return;
    }
    let mut class = load();
    class.get_or_add_dynamic(1, "_", "Ljava/lang/Object;");
    class.sync_counts();
    let mut out = Cursor::new(Vec::new());
    class.write(&mut out).expect("write");

    let dir = tempfile::tempdir().expect("tempdir");
    std::fs::write(dir.path().join("CondyExample.class"), out.into_inner())
        .expect("write class file");
    let output = Command::new("java")
        .arg("-cp")
        .arg(dir.path())
        .arg("CondyExample")
        .output()
        .expect("failed to run java");
    assert!(
        output.status.success(),
        "java exited with {}:\n{}",
        output.status,
        String::from_utf8_lossy(&output.stderr)
    );
    assert_eq!(String::from_utf8_lossy(&output.stdout), "int\n42\nnull\n");
}
